import test from "node:test";
import assert from "node:assert/strict";
import { extractCandidates } from "../lib/auto-capture.js";

test("extracts explicit first-person facts and a project deadline", () => {
	const candidates = extractCandidates("我叫林舟，我对花生过敏，我住在上海，我在做 HarmonyGo 项目，截止 2026-12-31。");
	assert.deepEqual(candidates, [
		{ subject: "self", predicate: "name", object: "林舟" },
		{ subject: "self", predicate: "allergy", object: "花生" },
		{ subject: "self", predicate: "city", object: "上海" },
		{ subject: "self", predicate: "works_on", object: "HarmonyGo" },
		{ subject: "HarmonyGo", predicate: "deadline", object: "2026-12-31" },
	]);
});

test("questions and pronouns do not become candidates", () => {
	assert.deepEqual(extractCandidates("我叫什么？我对什么过敏？"), []);
	assert.deepEqual(extractCandidates("她对虾过敏。"), []);
	assert.deepEqual(extractCandidates("今天天气怎么样？"), []);
});

test("relation and employer are captured without swallowing the other person", () => {
	const candidates = extractCandidates("我妈妈叫王芳；我在某某科技工作。");
	assert.deepEqual(candidates, [
		{ subject: "self", predicate: "employer", object: "某某科技" },
		{ subject: "self", predicate: "relation", object: "王芳", qualifier: "妈妈" },
	]);
});

test("the same fact mentioned twice yields one candidate", () => {
	const candidates = extractCandidates("我对花生过敏。我真的对花生过敏。");
	assert.deepEqual(candidates, [{ subject: "self", predicate: "allergy", object: "花生" }]);
});
